const crypto = require('crypto');

// The shared HMAC secret. Preferred: set WEBHOOK_HMAC_SECRET as an n8n
// environment variable. If env access is blocked on this instance, edit the
// FALLBACK_SECRET below to your shared secret (must match the sender/Postman).
const FALLBACK_SECRET = 'change-me-shared-secret';
let secret = FALLBACK_SECRET;
try {
  if (typeof $env !== 'undefined' && $env && $env.WEBHOOK_HMAC_SECRET) {
    secret = $env.WEBHOOK_HMAC_SECRET;
  }
} catch (e) {
  // env access is disabled on this instance; use FALLBACK_SECRET
}

const headers = $json.headers || {};
const query = $json.query || {};
const body = $json.body || {};

// The signing base: the raw request body when available, else the JSON body.
const rawBody = (typeof $json.rawBody === 'string' && $json.rawBody.length)
  ? $json.rawBody
  : JSON.stringify(body);

// Incoming signature header (supports "sha256=..." or bare hex).
const rawHeader = String(headers['x-signature'] || headers['x-hub-signature-256'] || '');
const providedSig = rawHeader.replace(/^sha256=/i, '').trim().toLowerCase();

let expectedSig = null;
let signatureValid = false;
if (secret) {
  expectedSig = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
  try {
    signatureValid =
      providedSig.length === expectedSig.length &&
      crypto.timingSafeEqual(Buffer.from(providedSig), Buffer.from(expectedSig));
  } catch (e) {
    signatureValid = false;
  }
}

return {
  signatureValid,
  secretConfigured: Boolean(secret),
  expectedSignature: expectedSig,
  providedSignature: providedSig || null,
  parsed: {
    headers,
    query,
    body,
  },
  receivedAt: new Date().toISOString(),
};
